from collections import Counter
def transform(g):
    H=len(g)
    cnt=Counter(c for row in g for c in row)
    bg=cnt.most_common(1)[0][0]
    div=[len(set(g[r]))==1 and g[r][0]!=bg for r in range(H)]
    segs=[]; cur=[]
    for r in range(H):
        if div[r]:
            if cur: segs.append(cur); cur=[]
        else: cur.append(r)
    if cur: segs.append(cur)
    def score(seg):
        return sum(1 for r in seg for c in g[r] if c!=bg)
    pat=max(segs,key=score)
    ph=len(pat)
    out=[row[:] for row in g]
    for seg in segs:
        if seg==pat: continue
        for i,r in enumerate(seg):
            out[r]=g[pat[0]+(i%ph)][:]
    return out

