def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(c for row in g for c in row)
    bg=cnt.most_common(1)[0][0]
    # candidate divider color: color of uniform full rows/cols that is not bg
    cand=set(g[r][0] for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg)
    cand|=set(g[0][c] for c in range(W) if len(set(g[r][c] for r in range(H)))==1 and g[0][c]!=bg)
    if not cand: return g
    dc=max(cand,key=lambda c:sum(row.count(c) for row in g))
    drows=[r for r in range(H) if all(g[r][c]==dc for c in range(W))]
    dcols=[c for c in range(W) if all(g[r][c]==dc for r in range(H))]
    def blocks(n,ds):
        bs=[];cur=[]
        for i in range(n):
            if i in ds:
                if cur: bs.append(cur);cur=[]
            else: cur.append(i)
        if cur: bs.append(cur)
        return bs
    rbs=blocks(H,set(drows)); cbs=blocks(W,set(dcols))
    regions=[(rs,cs) for rs in rbs for cs in cbs]
    def fillcount(rs,cs):
        return sum(1 for r in rs for c in cs if g[r][c]!=bg)
    pat=max(regions,key=fillcount)
    prs,pcs=pat
    ph,pw=len(prs),len(pcs)
    out=[row[:] for row in g]
    for rs,cs in regions:
        if (rs,cs)==pat: continue
        for i,r in enumerate(rs):
            for j,c in enumerate(cs):
                out[r][c]=g[prs[i%ph]][pcs[j%pw]]
    return out

